#include <iostream>
#include <string>
#include <vector>
using namespace std;

class Personagem {
public:
    Personagem(const string& nome, int vidaMax, int ataque, int defesa)
        : nome(nome), vida(vidaMax), vidaMax(vidaMax), ataque(ataque), defesa(defesa) {}

    string getNome() const { return nome; }
    int getVida() const { return vida; }
    int getVidaMax() const { return vidaMax; }
    int getAtaque() const { return ataque; }
    int getDefesa() const { return defesa; }
    bool estaVivo() const { return vida > 0; }

    int receberGolpe(int forca) {
        int dano = forca - defesa;
        if (dano < 1) {
            dano = 1;
        }
        vida -= dano;
        if (vida < 0) {
            vida = 0;
        }
        return dano;
    }

    int curar(int quantidade) {
        int antes = vida;
        vida += quantidade;
        if (vida > vidaMax) {
            vida = vidaMax;
        }
        return vida - antes;
    }

protected:
    string nome;
    int vida;
    int vidaMax;
    int ataque;
    int defesa;
};

class Inimigo : public Personagem {
public:
    Inimigo(const string& nome, int vidaMax, int ataque, int defesa, int ouro, const string& item)
        : Personagem(nome, vidaMax, ataque, defesa), ouro(ouro), item(item) {}

    int getOuro() const { return ouro; }
    string getItem() const { return item; }

private:
    int ouro;
    string item;
};

vector<Inimigo> criarMasmorra() {
    vector<Inimigo> masmorra;
    masmorra.push_back(Inimigo("Rato Gigante", 12, 3, 0, 5, "Poção"));
    masmorra.push_back(Inimigo("Goblin", 18, 5, 1, 12, "Poção"));
    masmorra.push_back(Inimigo("Ogro", 28, 6, 2, 30, "Coroa do Ogro"));
    return masmorra;
}

int contarVivos(const vector<Inimigo>& inimigos) {
    int vivos = 0;
    for (const Inimigo& inimigo : inimigos) {
        if (inimigo.estaVivo()) {
            vivos++;
        }
    }
    return vivos;
}

int main() {
    vector<Inimigo> masmorra = criarMasmorra();
    cout << "=== Bestiário da masmorra ===" << endl;
    for (const Inimigo& inimigo : masmorra) {
        cout << inimigo.getNome() << ": vida " << inimigo.getVida() << ", ataque " << inimigo.getAtaque()
             << ", defesa " << inimigo.getDefesa() << ", ouro " << inimigo.getOuro() << endl;
    }
    Personagem heroi("Ana", 30, 5, 2);
    int dano = masmorra[0].receberGolpe(heroi.getAtaque() + 10);
    cout << heroi.getNome() << " causa " << dano << " de dano em " << masmorra[0].getNome() << "." << endl;
    cout << "Inimigos de pé: " << contarVivos(masmorra) << endl;
    return 0;
}

