bool batalha(Personagem& heroi, Inimigo& inimigo) {
    cout << inimigo.getNome() << " aparece!" << endl;
    while (true) {
        cout << heroi.getNome() << " " << heroi.getVida() << "/" << heroi.getVidaMax() << " | "
