            cout << heroi.getNome() << " foge da batalha." << endl;
            return false;
        } else {
            cout << "Comando inválido." << endl;
            continue;
        }
        int forca = inimigo.getAtaque() + rolar(6);
        if (defendendo) {
            forca = forca / 2;
        }
